function checkBonusTrigger(){
  for(const k of ["health","pc","bud","mor","dean"]){
    if(STATE.stats[k] > 75 && !STATE.bonusFired[k]){
      STATE.bonusFired[k] = true;
      const pool = BONUS_SCENARIOS[k];
      return pool[Math.floor(Math.random() * pool.length)];
    }
  }
  return null;
}

